use serde_json::{Value,json};use sha2::{Sha256,Digest};use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/delta-pack175";
fn main(){let p=|s:&str|Path::new(R).join(s);let d=p("initial-native1");fs::create_dir(&d).unwrap();for f in["native1-plan.json","native1-pins.json","kernel.rs","kernel-template.rs"]{fs::copy(p(f),d.join(f)).unwrap();}fs::rename(p("native1"),d.join("runs")).unwrap();
 let s=fs::read_to_string(p("kernel.rs")).unwrap();assert_eq!(s.matches("->[__m512i;4]{").count(),1);assert_eq!(s.matches("[w0,w1,w2,w3]\n}").count(),1);assert_eq!(s.matches("let expected=core::array::from_fn").count(),1);let t=s.replace("->[__m512i;4]{","->[__m512i;4]{ unsafe{").replace("[w0,w1,w2,w3]\n}","[w0,w1,w2,w3]\n}} ").replace("let expected=core::array::from_fn","let expected:[[u64;4];8]=core::array::from_fn");fs::write(p("kernel.rs"),t).unwrap();
 let mut pins:Value=serde_json::from_slice(&fs::read(p("native1-pins.json")).unwrap()).unwrap();let h=|b:&[u8]|format!("{:x}",Sha256::digest(b));pins[format!("{R}/kernel.rs")]=json!(h(&fs::read(p("kernel.rs")).unwrap()));for f in["repair.rs"]{pins[format!("{R}/{f}")]=json!(h(&fs::read(p(f)).unwrap()));}fs::write(p("native-fixed-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let mut plan:Value=serde_json::from_slice(&fs::read(p("native1-plan.json")).unwrap()).unwrap();plan["source_pins"]=json!(p("native-fixed-pins.json"));fs::write(p("native-fixed-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();
 let s=fs::read_to_string(p("control.rs")).unwrap();assert_eq!(s.matches("verify(\"native1-pins.json\")").count(),1);fs::write(p("control-fixed.rs"),s.replace("verify(\"native1-pins.json\")","verify(\"native-fixed-pins.json\")")).unwrap();println!("Preserved original failure before any test; added explicit unsafe block and test array length; no arithmetic body changes");
}
